export interface CliConfig { command: string; args: string[]; verbose: boolean; }
export function parseArgs(argv: string[]): CliConfig {
  const raw = argv.slice(2);
  const verbose = raw.includes('--verbose');
  const filtered = raw.filter(a => a !== '--verbose');
  return { command: filtered[0] || 'help', args: filtered.slice(1), verbose };
}

